#include <stdint.h>
#include <stddef.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/times.h>

/* -------------------------------------------------------------------------- */
/*   ITM Register Definitions                                                 */
/* -------------------------------------------------------------------------- */
#define DEMCR               (*((volatile uint32_t *)0xE000EDFCU))
#define ITM_STIMULUS_PORT0  (*((volatile uint32_t *)0xE0000000U))
#define ITM_TRACE_EN        (*((volatile uint32_t *)0xE0000E00U))

/* -------------------------------------------------------------------------- */
/*   Function Prototypes                                                      */
/* -------------------------------------------------------------------------- */
void ITM_SendChar(uint8_t ch);
int __io_putchar(int ch);
int __io_getchar(void);

/* -------------------------------------------------------------------------- */
/*   ITM Send Function                                                        */
/* -------------------------------------------------------------------------- */
void ITM_SendChar(uint8_t ch)
{
    /* Enable TRCENA (bit 24 in DEMCR) */
    DEMCR |= (1 << 24);

    /* Enable stimulus port 0 */
    ITM_TRACE_EN |= (1 << 0);

    /* Wait for ITM port to be ready */
    while (!(ITM_STIMULUS_PORT0 & 1))
        ;

    /* Write the character to port 0 */
    ITM_STIMULUS_PORT0 = ch;
}

/* -------------------------------------------------------------------------- */
/*   I/O Redirection                                                          */
/* -------------------------------------------------------------------------- */

/* printf() redirection */
int __io_putchar(int ch)
{
    ITM_SendChar((uint8_t)ch);
    return ch;
}

/* scanf() redirection (ITM has no input) */
int __io_getchar(void)
{
    /* No input support for ITM; return EOF */
    return -1;
}

