/* Process and file-related stubs */
int _getpid(void) { return 1; }

int _kill(int pid, int sig)
{
    (void)pid;
    (void)sig;
    errno = EINVAL;
    return -1;
}

void _exit(int status)
{
    _kill(status, -1);
    while (1)
        ;
}

__attribute__((weak)) int _write(int file, char *ptr, int len)
{
    (void)file;
    for (int i = 0; i < len; i++)
    {
        __io_putchar(*ptr++);
    }
    return len;
}

__attribute__((weak)) int _read(int file, char *ptr, int len)
{
    (void)file;
    int i;
    int c;

    for (i = 0; i < len; i++)
    {
        c = __io_getchar();
        if (c == -1)
            return i; // No more data
        *ptr++ = (char)c;
    }

    return len;
}

